namespace sv_edb0452447884873ae2c090683ca4357.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// Each SignalR circuit (user/tab) gets its own instance.
/// </summary>
public sealed class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChanged;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        OnChanged?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChanged?.Invoke();
    }

    public void ApplyAll(ThemeMode theme, string accentColor)
    {
        Theme = theme;
        AccentColor = accentColor;
        OnChanged?.Invoke();
    }
}

@rendermode InteractiveServer
@inject ThemeService ThemeService
@inject IJSRuntime JS
@implements IDisposable

<span class="theme-indicator" title="Current theme" style="color: @ThemeService.AccentColor;">
    @GetThemeIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ApplyThemeToDocument();
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyThemeToDocument();
            StateHasChanged();
        });
    }

    private async Task ApplyThemeToDocument()
    {
        await JS.InvokeVoidAsync("applyTheme",
            ThemeService.Theme.ToString().ToLowerInvariant(),
            ThemeService.AccentColor);
    }

    private string GetThemeIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        ThemeMode.System => "💻",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleThemeChanged;
    }
}

@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<button class="btn btn-sm btn-outline-secondary theme-toggle" @onclick="CycleTheme"
        title="Toggle theme" style="border-color: @ThemeService.AccentColor;">
    @GetThemeIcon()
</button>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleChanged;
    }

    private void CycleTheme()
    {
        var next = ThemeService.Theme switch
        {
            ThemeMode.Light => ThemeMode.Dark,
            ThemeMode.Dark => ThemeMode.System,
            ThemeMode.System => ThemeMode.Light,
            _ => ThemeMode.Light
        };
        ThemeService.SetTheme(next);
    }

    private void HandleChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetThemeIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        ThemeMode.System => "💻",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <div class="btn-group d-block" role="group">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    <button type="button"
                            class="btn @(ThemeService.Theme == mode ? "btn-primary" : "btn-outline-primary")"
                            style="@(ThemeService.Theme == mode ? $"background-color:{ThemeService.AccentColor};border-color:{ThemeService.AccentColor};" : "")"
                            @onclick="() => ThemeService.SetTheme(mode)">
                        @GetIcon(mode) @mode
                    </button>
                }
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label" for="accentColor">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" id="accentColor" class="form-control form-control-color"
                       value="@ThemeService.AccentColor"
                       @onchange="OnAccentColorChanged" />
                <span class="text-muted">@ThemeService.AccentColor</span>
            </div>
        </div>
    </div>
</div>

<div class="mt-3 p-3 rounded" style="background-color: @ThemeService.AccentColor; color: white; max-width: 500px;">
    Preview: Current theme is <strong>@ThemeService.Theme</strong> with accent <strong>@ThemeService.AccentColor</strong>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleChanged;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    private void HandleChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private static string GetIcon(ThemeMode mode) => mode switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        ThemeMode.System => "💻",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleChanged;
    }
}

