@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <div class="btn-group d-block" role="group">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    <button type="button"
                            class="btn @(ThemeService.Theme == mode ? "btn-primary" : "btn-outline-primary")"
                            style="@(ThemeService.Theme == mode ? $"background-color:{ThemeService.AccentColor};border-color:{ThemeService.AccentColor};" : "")"
                            @onclick="() => ThemeService.SetTheme(mode)">
                        @GetIcon(mode) @mode
                    </button>
                }
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label" for="accentColor">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" id="accentColor" class="form-control form-control-color"
                       value="@ThemeService.AccentColor"
                       @onchange="OnAccentColorChanged" />
                <span class="text-muted">@ThemeService.AccentColor</span>
            </div>
        </div>
    </div>
</div>

<div class="mt-3 p-3 rounded" style="background-color: @ThemeService.AccentColor; color: white; max-width: 500px;">
    Preview: Current theme is <strong>@ThemeService.Theme</strong> with accent <strong>@ThemeService.AccentColor</strong>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleChanged;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    private void HandleChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private static string GetIcon(ThemeMode mode) => mode switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        ThemeMode.System => "💻",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleChanged;
    }
}

